// components/ScriptReader.js

import React, { useState, useCallback } from 'react';
import { FileText, UploadCloud } from 'lucide-react';
import * as mammoth from "mammoth"; // Change the import style

const ScriptReader = () => {
  const [scriptText, setScriptText] = useState('');
  const [fileName, setFileName] = useState('');

  console.log("Mammoth object (as namespace):", mammoth); // Check the imported object

  const handleFileUpload = useCallback(async (event) => {
    const file = event.target.files[0];

    if (file) {
      setFileName(file.name);
      if (file.type === 'text/plain') {
        const reader = new FileReader();
        reader.onload = (e) => {
          setScriptText(e.target.result);
          localStorage.setItem('melodicJustice_script', e.target.result);
        };
        reader.readAsText(file);
      } else if (file.type === 'application/msword' || file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
        try {
          const arrayBuffer = await file.arrayBuffer();
          const result = await mammoth.convert({
            arrayBuffer: arrayBuffer,
            outputFormat: "plain",
            styleMap: [
              "p[style-name='Centered'] => center:p", // Try a custom plain text marker
              "b => **",                             // Markdown-like bold
              "i => *",                              // Markdown-like italic
              // Add more style mappings as needed
            ]
          });
          setScriptText(result.value);
          localStorage.setItem('melodicJustice_script', result.value);
        } catch (error) {
          console.error("Error converting DOC/DOCX:", error);
          alert(`Error reading DOC/DOCX file: ${error.message}`);
        }
      } else {
        alert('Please upload a plain text (.txt), .doc, or .docx file.');
      }
    }
  }, [setScriptText, setFileName]);

  // Load saved script from localStorage on mount
  React.useEffect(() => {
    const savedScript = localStorage.getItem('melodicJustice_script');
    if (savedScript) {
      setScriptText(savedScript);
      setFileName('Saved Script');
    }
  }, []);

  return (
    <div className="p-6 max-w-4xl mx-auto text-white">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <FileText className="w-6 h-6 text-accent" />
          Script Viewer
        </h2>
        <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-primary rounded hover:bg-primaryDark transition">
          <UploadCloud className="w-5 h-5" />
          Upload Script
          <input
            type="file"
            accept=".txt,.doc,.docx"
            onChange={handleFileUpload}
            className="hidden" // Hide the default file input
          />
        </label>
      </div>
      <div className="bg-secondaryLight p-4 rounded shadow max-h-[70vh] overflow-y-auto whitespace-pre-wrap font-mono text-sm">
        {scriptText ? (
          <pre>{scriptText.replace(/\r\n/g, '\n')}</pre>
        ) : (
          <p className="text-midGray italic">No script loaded. Upload a `.txt`, `.doc`, or `.docx` file to begin.</p>
        )}
      </div>
      {fileName && <p className="text-midGray mt-2 text-sm italic">Viewing: {fileName}</p>}
    </div>
  );
};

export default ScriptReader;
